    internal static int PgtFirstDifference(emon.Port.Bitmap b, emon.Port.Buf raw) {
        // The index of the first sample of `b` that is not the byte `raw` holds, or -1.
        int rowb = emon.Port.BitmapW(b) * emon.Port.BitmapChannels(b);
        int n = emon.Port.BitmapH(b) * rowb;
        int i = 0;
        while (i < n) {
            if (emon.Port.BitmapU8(b, 0, i / rowb, i % rowb) != emon.Port.BufAt(raw, i)) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
