    [Xunit.Fact]
    public static void TestTheCodecRefusesADamagedFile() {
        // A flipped bit in the pixel data (the CRC), and a file cut short: `ic-failed`, 1.
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Cells row = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells pal = emon.Port.NewCells();
        emon.Port.Buf @out = emon.Port.NewBuf();
        emon.Port.Buf z = emon.Port.NewBuf();
        emon.Port.Buf raw = emon.Port.NewBuf();
        Pngprobe.PpBuild(1, ws, @out, z, raw, row, st, pal);
        PgtRead(0, 1, @out, raw, 0, "well formed");
        emon.Port.BufSet(@out, 60, emon.Port.BufAt(@out, 60) ^ 4);
        PgtRead(0, 1, @out, raw, 1, "the IDAT's CRC fails");
        emon.Port.BufSet(@out, 60, emon.Port.BufAt(@out, 60) ^ 4);
        PgtRead(0, 1, @out, raw, 0, "well formed again");
        emon.Port.BufTruncate(@out, emon.Port.BufLen(@out) - 20);
        PgtRead(0, 1, @out, raw, 1, "cut short");
    }
